#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<long long> c(n);
    for (int i = 0; i < n; i++) cin >> c[i];
    sort(c.begin(), c.end());
    long long bestRev = -1, bestTuition = 0;
    for (int i = 0; i < n; i++) {
        long long rev = c[i] * (n - i);
        if (rev > bestRev) {
            bestRev = rev;
            bestTuition = c[i];
        }
    }
    cout << bestRev << ' ' << bestTuition << '\n';
    return 0;
}

